9	const secrets = {
10	    STORAGE_CLIENT_ID: process.env.STORAGE_CLIENT_ID,
11	    STORAGE_CLIENT_SECRET: process.env.STORAGE_CLIENT_SECRET,
12	    AZURE_TENANT_ID: process.env.AZURE_TENANT_ID,
