24	    AUTH_MICROSOFT_CLIENT_ID: process.env.AUTH_MICROSOFT_CLIENT_ID,
25	    AUTH_MICROSOFT_CLIENT_SECRET: process.env.AUTH_MICROSOFT_CLIENT_SECRET,
26	
27	    CRON_SECRET: process.env.CRON_SECRET,
28	
29	    MAIL_FROM_ADDRESS: process.env.MAIL_FROM_ADDRESS ?? 'footy@toastboy.co.uk',
30	    MAIL_FROM_NAME: process.env.MAIL_FROM_NAME ?? 'Toastboy FC Mailer',
31	    MAIL_GRAPH_CLIENT_ID: process.env.MAIL_GRAPH_CLIENT_ID,
32	    MAIL_GRAPH_CLIENT_SECRET: process.env.MAIL_GRAPH_CLIENT_SECRET,
33	};
