35	/**
36	 * Secrets that are only required in production (e.g. Graph API email credentials).
37	 * These are allowed to be missing in development and CI environments.
38	 */
39	const productionOnlySecrets: ReadonlySet<keyof typeof secrets> = new Set([
40	    'MAIL_GRAPH_CLIENT_ID',
41	    'MAIL_GRAPH_CLIENT_SECRET',
42	]);
43	
44	let cachedSecrets: typeof secrets | null = null;
45	
46	function readFileIfExists(filePath: string): string | undefined {
47	    try {
48	        return fs.readFileSync(filePath, 'utf8');
49	    } catch (error: unknown) {
50	        if (
51	            typeof error === 'object' &&
52	            error !== null &&
53	            'code' in error &&
54	            (error as { code?: string }).code === 'ENOENT'
55	        ) {
56	            return undefined;
57	        }
58	
59	        throw normalizeUnknownError(error, {
60	            message: `Failed to read secret file at ${filePath}.`,
61	            details: {
62	                filePath,
63	            },
64	        });
65	    }
66	}
67	
68	/**
69	 * Load all secrets once and cache in memory.
70	 */
71	export function getSecrets(): typeof secrets {
72	    if (cachedSecrets !== null) {
73	        return cachedSecrets;
74	    }
75	
76	    const result = { ...secrets };
77	    const secretsDir = process.env.SECRETS_DIR;
78	
79	    if (secretsDir) {
80	        for (const key of Object.keys(secrets) as (keyof typeof secrets)[]) {
81	            const value = readFileIfExists(path.join(secretsDir, key));
82	
83	            if (value !== undefined) {
84	                result[key] = value;
85	            }
86	        }
87	    }
88	
89	    const isProduction = process.env.NODE_ENV === 'production';
90	    const missingSecrets = Object.entries(result)
91	        .filter(([key, value]) => {
92	            const isMissing =
93	                value === undefined || value === null || value === '';
94	            if (!isMissing) return false;
95	
96	            // Production-only secrets (e.g. Graph API email) are allowed to be
97	            // absent outside production; all other secrets are always required.
98	            if (
99	                !isProduction &&
100	                productionOnlySecrets.has(key as keyof typeof secrets)
101	            ) {
102	                return false;
103	            }
104	
105	            return true;
106	        })
107	        .map(([key]) => key);
108	
109	    // No route is statically prerendered (see docs/ontology.yaml / CLAUDE.md
110	    // architecture notes - everything is server-rendered on demand), so
111	    // secrets are only genuinely needed once a request comes in at runtime.
112	    // Next.js still imports route modules during `next build` to collect
113	    // their static config, which would otherwise trip this check for any
114	    // module that reads secrets at import time rather than per-request.
115	    const isBuildTimeCollection =
116	        process.env.NEXT_PHASE === PHASE_PRODUCTION_BUILD;
117	
118	    if (
119	        missingSecrets.length > 0 &&
120	        process.env.NODE_ENV !== 'test' &&
121	        !isBuildTimeCollection
122	    ) {
123	        throw new InternalError('Missing required secrets.', {
124	            details: {
125	                missingSecrets,
126	            },
127	        });
128	    }
129	
130	    cachedSecrets = result;
131	    return cachedSecrets;
132	}
